const payload = $json;
const msgPayload = payload.payload || payload;
const key = msgPayload.key || {};
const message = msgPayload.message || {};

const chatId = key.remoteJid || msgPayload.from || '';
const pushName = msgPayload.pushName || 'Cliente';
const text = (
  message.conversation ||
  message.extendedTextMessage?.text ||
  msgPayload.text ||
  ''
).toLowerCase().trim();

return [{ json: { chatId, text, pushName } }];

